def pack(payload):
    import random
    import time

    items = payload["items"]
    capacity = payload["capacity"]
    n = len(items)
    if n == 0:
        return []

    total = sum(items)
    lower_bound = (total + capacity - 1) // capacity
    start_time = time.time()
    TIME_LIMIT = 1.0
    rng = random.Random(12345)

    # ---------- basic constructor ----------
    def build(order):
        bins_load = []
        bins_items = []
        for idx in order:
            sz = items[idx]
            best_i = -1
            best_rem = capacity + 1
            for i, load in enumerate(bins_load):
                rem = capacity - load - sz
                if rem >= 0 and rem < best_rem:
                    best_rem = rem
                    best_i = i
            if best_i == -1:
                bins_load.append(sz)
                bins_items.append([idx])
            else:
                bins_load[best_i] += sz
                bins_items[best_i].append(idx)
        return bins_items, bins_load

    best_bins = None
    best_loads = None
    best_count = n + 1

    def consider(bins, loads):
        nonlocal best_bins, best_loads, best_count
        if len(bins) <= best_count:
            best_count = len(bins)
            best_bins = [b[:] for b in bins]
            best_loads = loads[:]

    # ---------- initial solutions ----------
    base_order = list(range(n))
    base_order.sort(key=lambda i: (-items[i], i))
    b, l = build(base_order)
    consider(b, l)

    if n <= 2000:
        indexed = base_order[:]
        for _ in range(8):
            groups = {}
            for i in indexed:
                groups.setdefault(items[i], []).append(i)
            new_order = []
            for sz in sorted(groups.keys(), reverse=True):
                g = groups[sz][:]
                rng.shuffle(g)
                new_order.extend(g)
            b, l = build(new_order)
            consider(b, l)
            if time.time() - start_time > TIME_LIMIT * 0.3:
                break

        for _ in range(5):
            new_order = sorted(
                range(n),
                key=lambda i: (-items[i] + rng.random() * 0.1, i)
            )
            b, l = build(new_order)
            consider(b, l)
            if time.time() - start_time > TIME_LIMIT * 0.5:
                break

    # ---------- minimum bin slack (MBS) constructor ----------
    def mbs_pack():
        remaining = base_order[:]
        bins_items = []
        bins_load = []

        while remaining:
            if time.time() - start_time > TIME_LIMIT * 0.8:
                for idx in remaining:
                    sz = items[idx]
                    best_i = -1
                    best_rem = capacity + 1
                    for bi, load in enumerate(bins_load):
                        rem = capacity - load - sz
                        if rem >= 0 and rem < best_rem:
                            best_rem = rem
                            best_i = bi
                    if best_i == -1:
                        bins_load.append(sz)
                        bins_items.append([idx])
                    else:
                        bins_load[best_i] += sz
                        bins_items[best_i].append(idx)
                break

            base = remaining[0]
            slack = capacity - items[base]
            chosen = [base]

            if slack > 0 and len(remaining) > 1:
                if slack <= 20000:
                    mask = (1 << (slack + 1)) - 1
                    bits = 1
                    reach_list = [1]
                    for j in range(1, len(remaining)):
                        sz = items[remaining[j]]
                        if sz <= slack:
                            bits = (bits | (bits << sz)) & mask
                        reach_list.append(bits)

                    best_sum = bits.bit_length() - 1
                    target = best_sum
                    for j in range(len(remaining) - 1, 0, -1):
                        if target <= 0:
                            break
                        idx = remaining[j]
                        sz = items[idx]
                        if sz <= target:
                            prev = reach_list[j - 1]
                            if (prev >> (target - sz)) & 1:
                                chosen.append(idx)
                                target -= sz
                else:
                    for idx in remaining[1:]:
                        if items[idx] <= slack:
                            chosen.append(idx)
                            slack -= items[idx]

            chosen_set = set(chosen)
            remaining = [idx for idx in remaining if idx not in chosen_set]
            load = sum(items[i] for i in chosen)
            bins_items.append(chosen)
            bins_load.append(load)

        return bins_items, bins_load

    if time.time() - start_time < TIME_LIMIT * 0.8:
        b, l = mbs_pack()
        consider(b, l)

    if best_count == lower_bound:
        return best_bins

    # ---------- exact solver for small instances ----------
    if n <= 45 and time.time() - start_time < TIME_LIMIT * 0.9:
        sorted_items = base_order[:]

        def exact_pack(K, deadline):
            if K * capacity < total:
                return None
            bins_rem = [capacity] * K
            assignment = [-1] * n

            def dfs(pos):
                if time.time() > deadline:
                    return False
                if pos == n:
                    return True
                idx = sorted_items[pos]
                sz = items[idx]
                candidates = [b for b in range(K) if bins_rem[b] >= sz]
                candidates.sort(key=lambda b: bins_rem[b])
                seen = set()
                for b in candidates:
                    rem = bins_rem[b]
                    if rem in seen:
                        continue
                    seen.add(rem)
                    bins_rem[b] -= sz
                    assignment[idx] = b
                    if dfs(pos + 1):
                        return True
                    bins_rem[b] += sz
                    assignment[idx] = -1
                return False

            if dfs(0):
                res = [[] for _ in range(K)]
                for idx, b in enumerate(assignment):
                    res[b].append(idx)
                res = [b for b in res if b]
                return res
            return None

        for K in range(lower_bound, best_count):
            if time.time() - start_time > TIME_LIMIT * 0.95:
                break
            deadline = min(start_time + TIME_LIMIT, time.time() + 0.3)
            res = exact_pack(K, deadline)
            if res is not None:
                best_bins = res
                best_count = len(res)
                if best_count == lower_bound:
                    return best_bins
                break
            if time.time() - start_time > TIME_LIMIT * 0.9:
                break

    # ---------- local search ----------
    bins = [b[:] for b in best_bins]
    loads = [sum(items[i] for i in b) for b in bins]

    def try_eliminate(skip, max_states=20000):
        nonlocal bins, loads
        if skip >= len(bins):
            return False
        items_to_move = bins[skip][:]
        if len(items_to_move) > 20:
            return False
        items_to_move.sort(key=lambda i: -items[i])
        other_bins = [i for i in range(len(bins)) if i != skip]
        caps = [capacity - loads[i] for i in other_bins]
        total_move = sum(items[i] for i in items_to_move)
        if sum(caps) < total_move:
            return False

        m = len(items_to_move)
        sizes = [items[i] for i in items_to_move]
        assignment = [-1] * m
        states = 0
        suffix = [0] * (m + 1)
        for i in range(m - 1, -1, -1):
            suffix[i] = suffix[i + 1] + sizes[i]

        def dfs(pos):
            nonlocal states
            states += 1
            if states > max_states or time.time() - start_time > TIME_LIMIT:
                return False
            if pos == m:
                return True
            if sum(caps) < suffix[pos]:
                return False
            sz = sizes[pos]
            candidates = [j for j in range(len(caps)) if caps[j] >= sz]
            candidates.sort(key=lambda j: caps[j] - sz)
            prev_cap = None
            for j in candidates:
                if prev_cap is not None and caps[j] == prev_cap:
                    continue
                prev_cap = caps[j]
                caps[j] -= sz
                assignment[pos] = j
                if dfs(pos + 1):
                    return True
                caps[j] += sz
                assignment[pos] = -1
            return False

        if dfs(0):
            new_bins = [b[:] for b in bins]
            new_loads = loads[:]
            for pos, j in enumerate(assignment):
                actual_bin = other_bins[j]
                idx = items_to_move[pos]
                new_bins[actual_bin].append(idx)
                new_loads[actual_bin] += items[idx]
            del new_bins[skip]
            del new_loads[skip]
            bins = new_bins
            loads = new_loads
            return True
        return False

    def try_repack_subset(bin_indices, target_bins, max_states=50000):
        nonlocal bins, loads
        items_to_pack = []
        for bi in bin_indices:
            items_to_pack.extend(bins[bi])
        total_load = sum(items[i] for i in items_to_pack)
        if total_load > target_bins * capacity:
            return False
        if len(items_to_pack) > 35:
            return False

        items_to_pack.sort(key=lambda i: -items[i])
        m = len(items_to_pack)
        sizes = [items[i] for i in items_to_pack]
        caps = [capacity] * target_bins
        assignment = [-1] * m
        states = 0
        suffix = [0] * (m + 1)
        for i in range(m - 1, -1, -1):
            suffix[i] = suffix[i + 1] + sizes[i]

        def dfs(pos):
            nonlocal states
            states += 1
            if states > max_states or time.time() - start_time > TIME_LIMIT:
                return False
            if pos == m:
                return True
            if sum(caps) < suffix[pos]:
                return False
            sz = sizes[pos]
            candidates = [b for b in range(target_bins) if caps[b] >= sz]
            candidates.sort(key=lambda b: caps[b] - sz)
            seen = set()
            for b in candidates:
                if caps[b] in seen:
                    continue
                seen.add(caps[b])
                caps[b] -= sz
                assignment[pos] = b
                if dfs(pos + 1):
                    return True
                caps[b] += sz
                assignment[pos] = -1
            return False

        if dfs(0):
            new_sub = [[] for _ in range(target_bins)]
            for pos, b in enumerate(assignment):
                new_sub[b].append(items_to_pack[pos])
            new_bins = []
            new_loads = []
            idx_set = set(bin_indices)
            for i, b in enumerate(bins):
                if i not in idx_set:
                    new_bins.append(b[:])
                    new_loads.append(loads[i])
            for b in new_sub:
                if b:
                    new_bins.append(b)
                    new_loads.append(sum(items[i] for i in b))
            bins = new_bins
            loads = new_loads
            return True
        return False

    def try_3_to_2(i, j, k):
        nonlocal bins, loads
        if time.time() - start_time > TIME_LIMIT:
            return False
        total_load = loads[i] + loads[j] + loads[k]
        if total_load > 2 * capacity:
            return False

        items_list = bins[i] + bins[j] + bins[k]

        if capacity > 5000:
            return try_repack_subset([i, j, k], 2, max_states=30000)

        lower = max(0, total_load - capacity)
        upper = capacity
        if lower > upper:
            return False

        mask = (1 << (upper + 1)) - 1
        bits = 1
        reach_list = [1]
        for idx in items_list:
            sz = items[idx]
            if sz <= upper:
                bits = (bits | (bits << sz)) & mask
            reach_list.append(bits)

        interval_mask = ((1 << (upper - lower + 1)) - 1) << lower
        possible = bits & interval_mask
        if not possible:
            return False

        target = possible.bit_length() - 1
        selected = set()
        target_sum = target
        for pos in range(len(items_list) - 1, -1, -1):
            if target_sum <= 0:
                break
            idx = items_list[pos]
            sz = items[idx]
            if sz <= target_sum:
                prev = reach_list[pos]
                if (prev >> (target_sum - sz)) & 1:
                    selected.add(pos)
                    target_sum -= sz

        bin1 = []
        bin2 = []
        for pos, idx in enumerate(items_list):
            if pos in selected:
                bin1.append(idx)
            else:
                bin2.append(idx)

        load1 = sum(items[i] for i in bin1)
        load2 = total_load - load1
        if load1 <= capacity and load2 <= capacity:
            new_bins = []
            new_loads = []
            idx_set = {i, j, k}
            for b_i, b in enumerate(bins):
                if b_i not in idx_set:
                    new_bins.append(b[:])
                    new_loads.append(loads[b_i])
            if bin1:
                new_bins.append(bin1)
                new_loads.append(load1)
            if bin2:
                new_bins.append(bin2)
                new_loads.append(load2)
            bins = new_bins
            loads = new_loads
            return True
        return False

    # ---------- improvement loop ----------
    while len(bins) > lower_bound and time.time() - start_time < TIME_LIMIT:
        improved = False

        # 1. merge two bins if possible
        best_pair = None
        best_load = -1
        m_bins = len(bins)
        if m_bins <= 200:
            for i in range(m_bins):
                for j in range(i + 1, m_bins):
                    if loads[i] + loads[j] <= capacity:
                        if loads[i] + loads[j] > best_load:
                            best_load = loads[i] + loads[j]
                            best_pair = (i, j)
        else:
            order_idx = sorted(range(m_bins), key=lambda i: loads[i])
            limit = min(m_bins, 100)
            for iii in range(limit):
                i = order_idx[iii]
                for jjj in range(iii + 1, limit):
                    j = order_idx[jjj]
                    if loads[i] + loads[j] <= capacity:
                        if loads[i] + loads[j] > best_load:
                            best_load = loads[i] + loads[j]
                            best_pair = (i, j)

        if best_pair is not None:
            i, j = best_pair
            bins[i].extend(bins[j])
            loads[i] += loads[j]
            del bins[j]
            del loads[j]
            improved = True
            continue

        # 2. try to eliminate one bin
        candidates = sorted(range(len(bins)), key=lambda i: (len(bins[i]), loads[i]))
        for skip in candidates:
            if len(bins[skip]) > 20:
                continue
            if try_eliminate(skip):
                improved = True
                break
        if improved:
            continue

        # 3. try 3 bins -> 2 bins
        cand = list(range(len(bins)))
        cand.sort(key=lambda i: (len(bins[i]), loads[i]))
        limit = min(len(cand), 25)
        found = False
        for a in range(limit):
            if found or time.time() - start_time > TIME_LIMIT:
                break
            i = cand[a]
            for b in range(a + 1, limit):
                if found or time.time() - start_time > TIME_LIMIT:
                    break
                j = cand[b]
                if loads[i] + loads[j] > 2 * capacity:
                    continue
                for c in range(b + 1, limit):
                    k = cand[c]
                    if loads[i] + loads[j] + loads[k] > 2 * capacity:
                        continue
                    if try_3_to_2(i, j, k):
                        found = True
                        improved = True
                        break
        if improved:
            continue

        # 4. try 4 bins -> 3 bins
        limit2 = min(len(cand), 12)
        found = False
        for a in range(limit2):
            if found or time.time() - start_time > TIME_LIMIT:
                break
            i = cand[a]
            for b in range(a + 1, limit2):
                if found or time.time() - start_time > TIME_LIMIT:
                    break
                j = cand[b]
                for c in range(b + 1, limit2):
                    if found or time.time() - start_time > TIME_LIMIT:
                        break
                    k = cand[c]
                    if len(bins[i]) + len(bins[j]) + len(bins[k]) > 20:
                        continue
                    for d in range(c + 1, limit2):
                        l = cand[d]
                        if len(bins[i]) + len(bins[j]) + len(bins[k]) + len(bins[l]) > 24:
                            continue
                        if loads[i] + loads[j] + loads[k] + loads[l] > 3 * capacity:
                            continue
                        if try_repack_subset([i, j, k, l], 3, max_states=20000):
                            found = True
                            improved = True
                            break
        if improved:
            continue

        # 5. random restart / perturbation
        restart_improved = False
        attempts = 0
        while time.time() - start_time < TIME_LIMIT * 0.9 and attempts < 5:
            attempts += 1
            new_order = list(range(n))
            new_order.sort(key=lambda i: (-items[i] + rng.random() * 0.5, i))
            b, l = build(new_order)
            if len(b) < len(bins):
                bins = [bb[:] for bb in b]
                loads = l[:]
                restart_improved = True
                break
        if restart_improved:
            improved = True
            continue

        break

    if len(bins) <= len(best_bins):
        best_bins = bins

    return best_bins

def pack(payload):
    import random
    import time
    import itertools

    items = payload["items"]
    capacity = payload["capacity"]
    n = len(items)
    if n == 0:
        return []

    start_time = time.time()
    if n <= 100:
        time_limit = 1.0
    else:
        time_limit = 0.8
    deadline = start_time + time_limit

    def get_loads(bins):
        return [sum(items[i] for i in b) for b in bins]

    def build_bins(order):
        bins = []
        loads = []
        for idx in order:
            sz = items[idx]
            best_i = -1
            best_rem = capacity + 1
            for i, load in enumerate(loads):
                rem = capacity - load - sz
                if rem >= 0 and rem < best_rem:
                    best_rem = rem
                    best_i = i
            if best_i == -1:
                bins.append([idx])
                loads.append(sz)
            else:
                bins[best_i].append(idx)
                loads[best_i] += sz
        return bins, loads

    def ffd(order):
        bins = []
        loads = []
        for idx in order:
            sz = items[idx]
            placed = False
            for i, load in enumerate(loads):
                if load + sz <= capacity:
                    bins[i].append(idx)
                    loads[i] += sz
                    placed = True
                    break
            if not placed:
                bins.append([idx])
                loads.append(sz)
        return bins, loads

    # Initial BFD
    order = list(range(n))
    order.sort(key=lambda i: (-items[i], i))
    best_bins, best_loads = build_bins(order)
    best_count = len(best_bins)

    # FFD
    bins, loads = ffd(order)
    if len(bins) < best_count:
        best_bins, best_loads = bins, loads
        best_count = len(bins)

    rng = random.Random(12345)

    # Randomized BFD
    for _ in range(3):
        if time.time() > deadline:
            break
        order_r = list(range(n))
        order_r.sort(key=lambda i: (-items[i], rng.random()))
        bins, loads = build_bins(order_r)
        if len(bins) < best_count:
            best_bins, best_loads = bins, loads
            best_count = len(bins)

    # Minimum Bin Slack (MBS) using bounded subset-sum DP
    def best_subset(counts, capacity, rng):
        groups = []
        sizes = list(counts.keys())
        rng.shuffle(sizes)
        for size in sizes:
            max_use = capacity // size
            cnt = min(counts[size], max_use)
            k = 1
            while cnt > 0:
                take = min(k, cnt)
                shift = size * take
                if shift <= capacity:
                    groups.append((size, take))
                cnt -= take
                k <<= 1
        rng.shuffle(groups)
        bits = 1
        history = [bits]
        mask = (1 << (capacity + 1)) - 1
        for size, mult in groups:
            shift = size * mult
            bits = (bits | (bits << shift)) & mask
            history.append(bits)
        max_sum = bits.bit_length() - 1
        cur = max_sum
        chosen = {}
        for idx in range(len(groups) - 1, -1, -1):
            prev = history[idx]
            if (prev >> cur) & 1:
                continue
            size, mult = groups[idx]
            chosen[size] = chosen.get(size, 0) + mult
            cur -= size * mult
        return chosen

    def mbs_solution(rng, deadline):
        size_lists = {}
        for idx, sz in enumerate(items):
            size_lists.setdefault(sz, []).append(idx)
        counts = {sz: len(lst) for sz, lst in size_lists.items()}
        bins = []
        while counts:
            if time.time() > deadline:
                return None
            chosen = best_subset(counts, capacity, rng)
            if not chosen:
                break
            bin_items = []
            for sz, mult in chosen.items():
                lst = size_lists[sz]
                for _ in range(mult):
                    bin_items.append(lst.pop())
                counts[sz] -= mult
                if counts[sz] == 0:
                    del counts[sz]
            bins.append(bin_items)
        return bins

    if capacity <= 2000 and n <= 100000:
        for seed in range(4):
            if time.time() > deadline:
                break
            rng_mbs = random.Random(seed * 1000 + 12345)
            bins_mbs = mbs_solution(rng_mbs, deadline)
            if bins_mbs is not None and len(bins_mbs) < best_count:
                best_bins = bins_mbs
                best_loads = get_loads(best_bins)
                best_count = len(best_bins)

    def exact_pack(items_indices, target, capacity, deadline):
        n_sub = len(items_indices)
        if n_sub == 0:
            return []
        sorted_indices = sorted(items_indices, key=lambda i: -items[i])
        szs = [items[i] for i in sorted_indices]
        total = sum(szs)
        if total > target * capacity:
            return None
        if target == 1:
            if total <= capacity:
                return [sorted_indices]
            else:
                return None

        # Heuristic BFD first
        loads_h = [0] * target
        assign_h = [-1] * n_sub
        for pos, sz in enumerate(szs):
            best_b = -1
            best_rem = capacity + 1
            for b in range(target):
                rem = capacity - loads_h[b] - sz
                if rem >= 0 and rem < best_rem:
                    best_rem = rem
                    best_b = b
            if best_b == -1:
                break
            loads_h[best_b] += sz
            assign_h[pos] = best_b
        else:
            res = [[] for _ in range(target)]
            for pos, b in enumerate(assign_h):
                res[b].append(sorted_indices[pos])
            return [b for b in res if b]

        loads = [0] * target
        assignment = [-1] * n_sub
        suffix = [0] * (n_sub + 1)
        for i in range(n_sub - 1, -1, -1):
            suffix[i] = suffix[i + 1] + szs[i]
        memo = set()

        def dfs(pos):
            if time.time() > deadline:
                return False
            if pos == n_sub:
                return True
            if suffix[pos] > target * capacity - sum(loads):
                return False
            state = (pos, tuple(sorted(loads)))
            if state in memo:
                return False
            sz = szs[pos]
            candidates = [b for b in range(target) if loads[b] + sz <= capacity]
            candidates.sort(key=lambda b: -loads[b])
            prev_load = -1
            for b in candidates:
                if loads[b] == prev_load:
                    continue
                prev_load = loads[b]
                loads[b] += sz
                assignment[pos] = b
                if dfs(pos + 1):
                    return True
                loads[b] -= sz
                assignment[pos] = -1
            memo.add(state)
            return False

        if dfs(0):
            res = [[] for _ in range(target)]
            for pos, b in enumerate(assignment):
                if b != -1:
                    res[b].append(sorted_indices[pos])
            return [b for b in res if b]
        return None

    def try_eliminate(bins, loads, skip, capacity, deadline):
        items_to_move = bins[skip][:]
        if not items_to_move:
            del bins[skip]
            del loads[skip]
            return True
        if len(items_to_move) > 20:
            return False
        items_to_move.sort(key=lambda i: -items[i])
        other_bins = [i for i in range(len(bins)) if i != skip]
        caps = [capacity - loads[i] for i in other_bins]
        total_move = sum(items[i] for i in items_to_move)
        if sum(caps) < total_move:
            return False
        m = len(items_to_move)
        sizes = [items[i] for i in items_to_move]
        assignment = [-1] * m
        states = 0
        max_states = 30000

        def dfs(pos):
            nonlocal states
            states += 1
            if states > max_states:
                return False
            if time.time() > deadline:
                return False
            if pos == m:
                return True
            sz = sizes[pos]
            candidates = [j for j in range(len(caps)) if caps[j] >= sz]
            candidates.sort(key=lambda j: caps[j] - sz)
            prev_cap = -1
            for j in candidates:
                if caps[j] == prev_cap:
                    continue
                prev_cap = caps[j]
                caps[j] -= sz
                assignment[pos] = j
                if dfs(pos + 1):
                    return True
                caps[j] += sz
                assignment[pos] = -1
            return False

        if dfs(0):
            for pos, j in enumerate(assignment):
                actual_bin = other_bins[j]
                idx = items_to_move[pos]
                bins[actual_bin].append(idx)
                loads[actual_bin] += items[idx]
            del bins[skip]
            del loads[skip]
            return True
        return False

    def try_local_repack(bins, loads, capacity, deadline):
        num = len(bins)
        if num <= 1:
            return None
        skip_candidates = sorted(range(num), key=lambda i: (loads[i], len(bins[i])))
        for skip in skip_candidates:
            if len(bins[skip]) > 18:
                continue
            if time.time() > deadline:
                return None
            others = [i for i in range(num) if i != skip]
            others.sort(key=lambda i: (loads[i], len(bins[i])))
            for m in range(1, min(3, len(others)) + 1):
                top = others[:min(6, len(others))]
                if len(top) < m:
                    continue
                for combo in itertools.combinations(top, m):
                    if time.time() > deadline:
                        return None
                    selected = (skip,) + combo
                    total_size = sum(loads[i] for i in selected)
                    if total_size > m * capacity:
                        continue
                    combined_items = []
                    for i in selected:
                        combined_items.extend(bins[i])
                    if len(combined_items) > 35:
                        continue
                    if m == 1:
                        if total_size <= capacity:
                            new_bin = combined_items
                            selected_set = set(selected)
                            new_bins = [b for i, b in enumerate(bins) if i not in selected_set]
                            new_loads = [loads[i] for i in range(num) if i not in selected_set]
                            new_bins.append(new_bin)
                            new_loads.append(total_size)
                            return new_bins, new_loads
                        continue
                    assignment_bins = exact_pack(combined_items, m, capacity, deadline)
                    if assignment_bins is not None:
                        selected_set = set(selected)
                        new_bins = []
                        new_loads = []
                        for i in range(num):
                            if i not in selected_set:
                                new_bins.append(bins[i])
                                new_loads.append(loads[i])
                        for b in assignment_bins:
                            if b:
                                load = sum(items[idx] for idx in b)
                                new_bins.append(b)
                                new_loads.append(load)
                        return new_bins, new_loads
        return None

    # Local search on best solution
    bins = [b[:] for b in best_bins]
    loads = best_loads[:]
    total_size = sum(items)
    LB = (total_size + capacity - 1) // capacity

    while len(bins) > LB and time.time() < deadline:
        improved = False

        # Greedy merges
        idxs = sorted(range(len(bins)), key=lambda i: loads[i])
        for i in range(len(idxs)):
            for j in range(i + 1, len(idxs)):
                a = idxs[i]
                b = idxs[j]
                if loads[a] + loads[b] <= capacity:
                    bins[a].extend(bins[b])
                    loads[a] += loads[b]
                    del bins[b]
                    del loads[b]
                    improved = True
                    break
            if improved:
                break
        if improved:
            continue

        # Try to eliminate one bin
        candidates = sorted(range(len(bins)), key=lambda i: (loads[i], len(bins[i])))
        for skip in candidates:
            if len(bins[skip]) > 20:
                continue
            if try_eliminate(bins, loads, skip, capacity, deadline):
                improved = True
                break
        if improved:
            continue

        # Try repacking a small group of bins
        res = try_local_repack(bins, loads, capacity, deadline)
        if res is not None:
            bins, loads = res
            improved = True
        if not improved:
            break

    # Random ruin/recreate if time remains
    if time.time() < deadline and len(bins) > LB:
        rng2 = random.Random(999)
        attempts = 0
        while time.time() < deadline and attempts < 10 and len(bins) > LB:
            attempts += 1
            num = len(bins)
            if num < 3:
                break
            k = rng2.randint(2, min(5, num))
            selected = rng2.sample(range(num), k)
            total_size = sum(loads[i] for i in selected)
            target = k - 1
            if total_size > target * capacity:
                continue
            combined_items = []
            for i in selected:
                combined_items.extend(bins[i])
            if len(combined_items) > 40:
                continue
            assignment_bins = exact_pack(combined_items, target, capacity, deadline)
            if assignment_bins is not None:
                selected_set = set(selected)
                new_bins = []
                new_loads = []
                for i in range(num):
                    if i not in selected_set:
                        new_bins.append(bins[i])
                        new_loads.append(loads[i])
                for b in assignment_bins:
                    if b:
                        load = sum(items[idx] for idx in b)
                        new_bins.append(b)
                        new_loads.append(load)
                if len(new_bins) < len(bins):
                    bins = new_bins
                    loads = new_loads

    return bins

def pack(payload):
    import time
    import random
    import itertools

    items = payload["items"]
    capacity = payload["capacity"]
    n = len(items)
    if n == 0:
        return []

    total_size = sum(items)
    lower_bound = (total_size + capacity - 1) // capacity

    def build(order, mode):
        bins = []
        if mode == 'best':
            for idx in order:
                sz = items[idx]
                best_i = -1
                best_rem = capacity + 1
                for i, (load, _) in enumerate(bins):
                    rem = capacity - load - sz
                    if rem >= 0 and rem < best_rem:
                        best_rem = rem
                        best_i = i
                if best_i == -1:
                    bins.append([sz, [idx]])
                else:
                    bins[best_i][0] += sz
                    bins[best_i][1].append(idx)
        elif mode == 'first':
            for idx in order:
                sz = items[idx]
                placed = False
                for i, (load, _) in enumerate(bins):
                    if load + sz <= capacity:
                        bins[i][0] += sz
                        bins[i][1].append(idx)
                        placed = True
                        break
                if not placed:
                    bins.append([sz, [idx]])
        elif mode == 'worst':
            for idx in order:
                sz = items[idx]
                best_i = -1
                best_rem = -1
                for i, (load, _) in enumerate(bins):
                    if load + sz <= capacity:
                        rem = capacity - load - sz
                        if rem > best_rem:
                            best_rem = rem
                            best_i = i
                if best_i == -1:
                    bins.append([sz, [idx]])
                else:
                    bins[best_i][0] += sz
                    bins[best_i][1].append(idx)
        return bins

    overall_start = time.time()
    time_limit = 0.9

    orders = []
    orders.append(sorted(range(n), key=lambda i: (-items[i], i)))
    orders.append(sorted(range(n), key=lambda i: (items[i], i)))

    rng = random.Random(12345)
    num_random = 8 if n <= 500 else 3
    for _ in range(num_random):
        groups = {}
        for i in range(n):
            groups.setdefault(items[i], []).append(i)
        order = []
        for sz in sorted(groups.keys(), reverse=True):
            g = groups[sz][:]
            rng.shuffle(g)
            order.extend(g)
        orders.append(order)

    if n <= 80:
        for _ in range(5):
            order = list(range(n))
            rng.shuffle(order)
            orders.append(order)

    best_bins = None
    best_count = n + 1

    for order in orders:
        if time.time() - overall_start > 0.25:
            break
        b = build(order, 'best')
        if len(b) < best_count:
            best_count = len(b)
            best_bins = b
        if order is orders[0]:
            b2 = build(order, 'first')
            if len(b2) < best_count:
                best_count = len(b2)
                best_bins = b2
            b3 = build(order, 'worst')
            if len(b3) < best_count:
                best_count = len(b3)
                best_bins = b3

    if best_bins is None:
        best_bins = build(orders[0], 'best')

    bins = [b[1][:] for b in best_bins]
    loads = [b[0] for b in best_bins]

    if len(bins) <= lower_bound:
        return bins

    def repack_2(inds, total_load):
        if total_load > 2 * capacity:
            return None
        if total_load <= capacity:
            return [inds[:]]

        m = len(inds)
        if capacity <= 50000 and m <= 500:
            bits = 1
            bits_list = [1]
            mask = (1 << (capacity + 1)) - 1
            for idx in inds:
                sz = items[idx]
                bits = (bits | (bits << sz)) & mask
                bits_list.append(bits)

            low = total_load - capacity
            if low < 0:
                low = 0
            if low > capacity:
                return None

            range_mask = ((1 << (capacity + 1)) - 1) ^ ((1 << low) - 1)
            possible = bits & range_mask
            if possible == 0:
                return None

            target = possible.bit_length() - 1
            subset = []
            rem = target
            for i in range(m - 1, -1, -1):
                idx = inds[i]
                sz = items[idx]
                if rem >= sz and ((bits_list[i] >> (rem - sz)) & 1):
                    subset.append(idx)
                    rem -= sz

            subset_set = set(subset)
            bin1 = subset
            bin2 = [idx for idx in inds if idx not in subset_set]
            if sum(items[x] for x in bin1) <= capacity and sum(items[x] for x in bin2) <= capacity:
                return [b for b in (bin1, bin2) if b]

        sizes = [(items[i], i) for i in inds]
        sizes.sort(key=lambda x: -x[0])
        caps = [capacity, capacity]
        assignment = [-1] * len(sizes)
        states = 0
        max_states = 20000

        def dfs(pos):
            nonlocal states
            states += 1
            if states > max_states:
                return False
            if pos == len(sizes):
                return True
            sz, idx = sizes[pos]
            for j in range(2):
                if caps[j] >= sz:
                    if j == 1 and caps[0] == caps[1]:
                        continue
                    caps[j] -= sz
                    assignment[pos] = j
                    if dfs(pos + 1):
                        return True
                    caps[j] += sz
                    assignment[pos] = -1
            return False

        if dfs(0):
            res = [[], []]
            for pos, j in enumerate(assignment):
                res[j].append(sizes[pos][1])
            return [b for b in res if b]
        return None

    def repack_general(inds, t, total_load):
        if total_load > t * capacity:
            return None
        if total_load <= capacity:
            return [inds[:]]
        if t == 2:
            return repack_2(inds, total_load)

        sizes = [(items[i], i) for i in inds]
        sizes.sort(key=lambda x: -x[0])
        caps = [capacity] * t
        assignment = [-1] * len(sizes)
        states = 0
        max_states = 5000 if len(sizes) > 30 else 20000
        memo = set()

        def dfs(pos):
            nonlocal states
            states += 1
            if states > max_states:
                return False
            if pos == len(sizes):
                return True

            key = (pos, tuple(sorted(caps)))
            if key in memo:
                return False

            sz, idx = sizes[pos]
            cand = [j for j in range(t) if caps[j] >= sz]
            cand.sort(key=lambda j: caps[j])
            prev = -1
            for j in cand:
                if caps[j] == prev:
                    continue
                prev = caps[j]
                caps[j] -= sz
                assignment[pos] = j
                if dfs(pos + 1):
                    return True
                caps[j] += sz
                assignment[pos] = -1

            memo.add(key)
            return False

        if dfs(0):
            res = [[] for _ in range(t)]
            for pos, j in enumerate(assignment):
                res[j].append(sizes[pos][1])
            return [b for b in res if b]
        return None

    while len(bins) > lower_bound and time.time() - overall_start < time_limit:
        improved = False
        B = len(bins)

        order_bins = sorted(range(B), key=lambda i: loads[i])
        for i_pos in range(B):
            if improved:
                break
            i = order_bins[i_pos]
            for j_pos in range(i_pos + 1, B):
                j = order_bins[j_pos]
                if loads[i] + loads[j] <= capacity:
                    bins[i].extend(bins[j])
                    loads[i] += loads[j]
                    del bins[j]
                    del loads[j]
                    improved = True
                    break
        if improved:
            continue

        if B >= 3:
            cand_bins = sorted(range(B), key=lambda i: (loads[i], len(bins[i])))
            M = min(B, 40)
            cand = cand_bins[:M]
            attempts = 0
            max_attempts = 1500
            found = False

            for a in range(len(cand)):
                if found or time.time() - overall_start > time_limit:
                    break
                i = cand[a]
                for b in range(a + 1, len(cand)):
                    if found or time.time() - overall_start > time_limit:
                        break
                    j = cand[b]
                    for c in range(b + 1, len(cand)):
                        if found or time.time() - overall_start > time_limit:
                            break
                        attempts += 1
                        if attempts > max_attempts:
                            break
                        k = cand[c]
                        total_load = loads[i] + loads[j] + loads[k]
                        if total_load > 2 * capacity:
                            continue
                        inds = bins[i] + bins[j] + bins[k]
                        res = repack_2(inds, total_load)
                        if res is not None:
                            rem = sorted([i, j, k], reverse=True)
                            for idx in rem:
                                del bins[idx]
                                del loads[idx]
                            for b_items in res:
                                load = sum(items[x] for x in b_items)
                                bins.append(b_items)
                                loads.append(load)
                            found = True
                            break
                    if found:
                        break
                if found:
                    break
            if found:
                improved = True
                continue

        if B >= 4 and time.time() - overall_start < time_limit:
            cand_bins = sorted(range(B), key=lambda i: (loads[i], len(bins[i])))
            M = min(B, 25)
            cand = cand_bins[:M]
            attempts = 0
            max_attempts = 800
            found = False

            for a in range(len(cand)):
                if found or time.time() - overall_start > time_limit:
                    break
                i = cand[a]
                for b in range(a + 1, len(cand)):
                    if found or time.time() - overall_start > time_limit:
                        break
                    j = cand[b]
                    for c in range(b + 1, len(cand)):
                        if found or time.time() - overall_start > time_limit:
                            break
                        k = cand[c]
                        for d in range(c + 1, len(cand)):
                            if found or time.time() - overall_start > time_limit:
                                break
                            attempts += 1
                            if attempts > max_attempts:
                                break
                            l = cand[d]
                            total_load = loads[i] + loads[j] + loads[k] + loads[l]
                            if total_load > 3 * capacity:
                                continue
                            inds = bins[i] + bins[j] + bins[k] + bins[l]
                            res = repack_general(inds, 3, total_load)
                            if res is not None:
                                rem = sorted([i, j, k, l], reverse=True)
                                for idx in rem:
                                    del bins[idx]
                                    del loads[idx]
                                for b_items in res:
                                    load = sum(items[x] for x in b_items)
                                    bins.append(b_items)
                                    loads.append(load)
                                found = True
                                break
                        if found:
                            break
                    if found:
                        break
                if found:
                    break
            if found:
                improved = True
                continue

        if B >= 5 and time.time() - overall_start < time_limit:
            cand_bins = sorted(range(B), key=lambda i: (loads[i], len(bins[i])))
            M = min(B, 15)
            cand = cand_bins[:M]
            attempts = 0
            max_attempts = 200
            found = False

            for comb in itertools.combinations(cand, 5):
                if found or time.time() - overall_start > time_limit:
                    break
                attempts += 1
                if attempts > max_attempts:
                    break
                total_load = sum(loads[idx] for idx in comb)
                if total_load > 4 * capacity:
                    continue
                inds = []
                for idx in comb:
                    inds.extend(bins[idx])
                res = repack_general(inds, 4, total_load)
                if res is not None:
                    rem = sorted(comb, reverse=True)
                    for idx in rem:
                        del bins[idx]
                        del loads[idx]
                    for b_items in res:
                        load = sum(items[x] for x in b_items)
                        bins.append(b_items)
                        loads.append(load)
